from pathlib import Path
import sys
p=Path(sys.argv[1])
source=(p/"tools/checkpoint_chain_iteration.py").read_text(encoding="utf-8")
source=source.replace('"""Archive the frozen integrated chain and preserve historical source evidence."""','"""Archive the frozen full-width DLO capacity evidence."""')
source=source.replace('p.add_argument("--checkpoint",type=Path,required=True)','p.add_argument("--fixture",type=Path,required=True)')
start=source.index('    frozen=json.loads')
end=source.index('    snapshot=iteration/',start)
body="    frozen=json.loads((iteration/\"plan/freeze-v1.json\").read_text())\n    intact={}\n    for name,digest in frozen[\"files\"].items():\n        intact[name]=sha(project/\"tools\"/name)==digest==sha(iteration/\"validator\"/name)\n    for name,digest in frozen[\"runtime\"].items():\n        intact[\"runtime:\"+name]=sha(project/\"src/h3_omni_adapter\"/name)==digest\n    intact[\"gates\"]=sha(iteration/\"plan/FROZEN-GATES.zh-CN.txt\")==frozen[\"gates_sha256\"]\n    fixture=json.loads((a.fixture/\"fixture-manifest.json\").read_text())\n    intact[\"fixture_files\"]=all(sha(a.fixture/v[\"file\"])==v[\"sha256\"] for v in fixture)\n    old=root/\"prototypes/2026-10-22-synthetic-loader\"\n    original=json.loads((old/\"plan/freeze.json\").read_text())[\"files\"]\n    old_intact=all(sha(old/name)==digest for name,digest in original.items())\n    if not all(intact.values()) or not old_intact:\n        raise RuntimeError(\"frozen source or fixture mismatch\")\n    runs=[]\n    for path in sorted((iteration/\"results\").glob(\"*/trial/result.json\")):\n        value=json.loads(path.read_text())\n        worker=value.get(\"worker\",{})\n        checks=worker.get(\"checks\",[])\n        required=frozen[\"required_\"+value[\"mode\"]+\"_checks\"]\n        complete=len(checks)==len(required) and all(c[\"ok\"] for c in checks) and set(c[\"name\"] for c in checks)==set(required)\n        runs.append({\"run\":path.parent.parent.name,\"exit_code\":value[\"exit_code\"],\n                     \"checks_ok\":sum(c[\"ok\"] for c in checks),\"checks_total\":len(checks),\n                     \"frozen_expected\":len(required),\"frozen_checks_complete\":complete,\n                     \"mode\":value[\"mode\"],\"geometry\":worker.get(\"geometry\"),\"budget\":worker.get(\"budget\"),\n                     \"export_stats\":worker.get(\"export_stats\"),\"actual_slots\":worker.get(\"actual_slots\"),\n                     \"phases\":worker.get(\"phases\"),\"monitor\":value.get(\"monitor\"),\n                     \"cuda_peak_allocated_bytes\":worker.get(\"cuda_peak_allocated_bytes\"),\n                     \"cuda_peak_reserved_bytes\":worker.get(\"cuda_peak_reserved_bytes\"),\n                     \"worker_peak_rss_bytes\":worker.get(\"peak_rss_bytes\"),\n                     \"execution_error\":worker.get(\"execution_error\") or value.get(\"execution_error\")})\n    summary={\"updated_utc\":datetime.now(UTC).isoformat(),\"campaign_verdict\":\"INCONCLUSIVE\",\n             \"scope\":\"real-width one-block native DLO conversion, transport and repeated sampling capacity\",\n             \"real_model_downloaded\":False,\"real_video_generated\":False,\"audio_decoded\":False,\n             \"full_model_fit_proven\":False,\"generic_cli_integrated\":False,\n             \"runtime_changed_this_iteration\":False,\"independent_review\":False,\"runs\":runs,\n             \"frozen_intact\":intact,\"original_freeze_intact\":old_intact,\n             \"path_redacted_files\":redacted,\"next\":\"plan/NEXT-STEPS.zh-CN.txt\"}\n"
source=source[:start]+body+source[end:]
(p/"tools/checkpoint_fullwidth_iteration.py").write_text(source,encoding="utf-8")
